// priority: 0
// Reward definitions are generated by kubejs/tools/build_yakuman_certificates.py.
const yakumanCertificateCatalog = JsonIO.read('kubejs/config/yakuman_certificates.json');
if (!yakumanCertificateCatalog || !yakumanCertificateCatalog.certificates) {
    throw new Error('Missing kubejs/config/yakuman_certificates.json');
}

StartupEvents.registry('item', event => {
    yakumanCertificateCatalog.certificates.forEach(certificate => {
        event.create('yakuman_certificate_' + certificate.key)
            .rarity('epic')
            .maxStackSize(64)
            .fireResistant()
            .texture('kubejs:item/yakuman_certificate')
            .tag('kubejs:yakuman_certificates')
            .tag('kubejs:yakuman_certificates/' + certificate.family);
    });
});
